// ==========================================
// LUNAS WIRKUNG: HYPNOTISCHES STARREN (ZERZAL)
//
// - genau ein lebendiges Ziel
// - nicht auf sich selbst
// - Reichweite: 8 Schritt
// - Dauer: QS × 5 Kampfrunden
// - Zielbewegung wird verhindert
// - Wirkender bewegt sich: Hypnose endet
// - Ziel wird erfolgreich angegriffen: Hypnose endet
// - gekoppelte Effekte über Block 6
// - atomarer Rollback bei Teilfehlern
// - Ziel gespeichert, kein neues Target
// - eine gemeinsame Karte + „Effekt anwenden“
// ==========================================


// +++ 0 - WÄCHTERMODUS ++++++++++++++++++++++++++++++++++++++++

if (typeof args !== "undefined" && args[0] === "WeckerAufruf") {
    const vollerName = "Hypnotisches Starren (Zerzal)";

    if (globalThis._dskHypnosePreUpdateHook) Hooks.off("preUpdateToken", globalThis._dskHypnosePreUpdateHook);
    if (globalThis._dskHypnoseUpdateHook) Hooks.off("updateToken", globalThis._dskHypnoseUpdateHook);
    if (globalThis._dskHypnoseSchadenHook) Hooks.off("createChatMessage", globalThis._dskHypnoseSchadenHook);
    if (globalThis._dskHypnoseCleanupHook) Hooks.off("preDeleteActiveEffect", globalThis._dskHypnoseCleanupHook);
    globalThis._dskHypnoseCleanupAktiv ||= new Set();

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch { return null; }
    };

    // +++ 0.1 - ZIELBEWEGUNG BLOCKIEREN +++++++++++++++++++++++

    globalThis._dskHypnosePreUpdateHook = Hooks.on("preUpdateToken", (tokenDoc, change, options, userId) => {
        if (change.x === undefined && change.y === undefined) return true;

        const effekt = tokenDoc.actor?.effects?.find(e =>
            !e.disabled && (e.name || e.label || "") === vollerName &&
            e.getFlag("dsk", "isHypnotisiert") === true
        );
        if (!effekt) return true;

        if (game.user.id === userId) {
            ui.notifications.warn(`Luna sagt 🌙: ${tokenDoc.name} ist hypnotisiert und völlig erstarrt!`);
        }
        return false;
    });

    // +++ 0.2 - WIRKENDER BEWEGT SICH +++++++++++++++++++++++++

    globalThis._dskHypnoseUpdateHook = Hooks.on("updateToken", async (tokenDoc, change) => {
        if (!game.user.isGM || (change.x === undefined && change.y === undefined)) return;

        const effekt = tokenDoc.actor?.effects?.find(e =>
            !e.disabled && (e.name || e.label || "") === vollerName &&
            e.getFlag("dsk", "isHypnoseCaster") === true
        );
        if (!effekt) return;

        ui.notifications.info(`Luna sagt 🌙: Hypnose gebrochen – ${tokenDoc.name} hat sich bewegt!`);
        await effekt.delete();
    });

    // +++ 0.3 - ZIEL WIRD ERFOLGREICH ANGEGRIFFEN +++++++++++++

    globalThis._dskHypnoseSchadenHook = Hooks.on("createChatMessage", async message => {
        if (!game.user.isGM || message.speaker?.alias === "System" || message.flags?.dsk?.isWatcherMsg) return;

        const DSK_FW = globalThis.DSK;
        const angriff = DSK_FW?.Schaden?.LeseAngriff?.(message);
        if (!angriff?.verteidigerName || angriff.schaden <= 0) return;

        const gelesen = DSK_FW.Schaden.NormalisiereName(angriff.verteidigerName);

        for (const token of canvas.tokens?.placeables || []) {
            const actor = token?.actor;
            if (!actor) continue;

            const effekt = actor.effects.find(e =>
                !e.disabled && (e.name || e.label || "") === vollerName &&
                e.getFlag("dsk", "isHypnotisiert") === true
            );
            if (!effekt) continue;

            const tokenName = DSK_FW.Schaden.NormalisiereName(token.name);
            const actorName = DSK_FW.Schaden.NormalisiereName(actor.name);
            if (gelesen !== tokenName && gelesen !== actorName) continue;

            ui.notifications.info(`Luna sagt 🌙: Hypnose gebrochen – ${token.name} wurde erfolgreich angegriffen!`);
            await effekt.delete();
        }
    });

    // +++ 0.4 - GEKOPPELTEN PARTNEREFFEKT ENTFERNEN +++++++++++

    globalThis._dskHypnoseCleanupHook = Hooks.on("preDeleteActiveEffect", async effect => {
        if (!game.user.isGM || !effect || (effect.name || effect.label || "") !== vollerName) return;

        const verbindungsId = effect.getFlag("dsk", "verbindungsId");
        const partnerUuid = effect.getFlag("dsk", "partnerUuid");
        if (!verbindungsId || !partnerUuid || globalThis._dskHypnoseCleanupAktiv.has(verbindungsId)) return;

        globalThis._dskHypnoseCleanupAktiv.add(verbindungsId);

        try {
            const partnerActor = await ladeActor(partnerUuid);
            const partnerEffekt = partnerActor?.effects?.find(e =>
                (e.name || e.label || "") === vollerName &&
                e.getFlag("dsk", "verbindungsId") === verbindungsId
            );
            if (partnerEffekt) await partnerEffekt.delete();
        } finally {
            setTimeout(() => globalThis._dskHypnoseCleanupAktiv.delete(verbindungsId), 500);
        }
    });

    globalThis._dskHypnoseInit = true;
    return;
}


// +++ 1 - NORMALE AUSFÜHRUNG ++++++++++++++++++++++++++++++++++

(async function () {
const macroUuid = this?.uuid || null;

// +++ 2 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
    !globalThis.DSK?.Wesen?.IstLebendig || !globalThis.DSK?.Geometrie?.Distanz ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute(); await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden || !DSK_FW?.Target?.Actor ||
    !DSK_FW?.Wesen?.IstLebendig || !DSK_FW?.Geometrie?.Distanz ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 3 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Hypnotisches Starren", vollerName = "Hypnotisches Starren (Zerzal)", ahne = "Zerzal";
const endeKey = "hypnotischesStarrenZerzal", flagKey = "pendingHypnotischesStarrenZerzal";
const reichweite = 8;
const endeText = "Der unheilvolle Blickkontakt bricht ab. Die Hypnose endet und die Erstarrung löst sich.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 4 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const ladeZiel = async daten => {
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const findeEffekte = (actor, flag) => (actor?.effects || []).filter(e =>
    (e.name || e.label || "") === vollerName && e.getFlag("dsk", flag) === true
);

const beschreibungFuer = (casterName, targetName) =>
    `<b>${casterName}</b> nimmt ununterbrochenen Blickkontakt mit <b>${targetName}</b> auf.` +
    `<br><br>Das Ziel verliert sich im unheilvollen Blick und bleibt regungslos stehen.` +
    `<br><br>Die Wirkung endet, wenn das Ziel erfolgreich angegriffen wird oder der Wirkende sich bewegt.` +
    `<br><b>Zielkategorie:</b> Lebewesen<br><b>Reichweite:</b> ${reichweite} Schritt`;

// +++ 5 - GEKOPPELTE EFFEKTE ÜBER BLOCK 6 ++++++++++++++++++++

const wendeHypnoseAn = async ({ casterActor, casterName, targetActor, targetName, qs, verbindungsId }) => {
    if (!casterActor || !targetActor) return false;

    const alteEffekte = [
        ...findeEffekte(casterActor, "isHypnoseCaster"),
        ...findeEffekte(targetActor, "isHypnotisiert")
    ];
    for (const effekt of alteEffekte) await effekt.delete();

    const dauerRunden = qs * 5;
    let casterEffekt = null, zielEffekt = null;

    try {
        casterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: `Du starrst <b>${targetName}</b> in die Augen. Bewegst du dich, bricht die Hypnose!`,
            gabeZiel: "", qs, ziel: casterActor,
            duration: { rounds: dauerRunden, startTime: game.time.worldTime }, showIcon: 1,
            flags: { dsk: {
                isHypnoseCaster: true, casterUuid: casterActor.uuid, qs,
                verbindungsId, partnerUuid: targetActor.uuid
            }}
        });

        if (!casterEffekt) throw new Error("Wirkendeneffekt fehlt.");

        zielEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: `Hypnotisiert von <b>${casterName}</b>. Jede Bewegung ist unmöglich, bis der Blickkontakt bricht!`,
            gabeZiel: "", qs, ziel: targetActor,
            changes: [{ key: "system.status.paralyzed", mode: 2, value: 1 }],
            duration: { rounds: dauerRunden, startTime: game.time.worldTime }, showIcon: 1,
            flags: { dsk: {
                isHypnotisiert: true, casterUuid: casterActor.uuid, qs,
                verbindungsId, partnerUuid: casterActor.uuid,
                wirkungsende: {
                    sfName: endeKey, basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }}
        });

        if (!zielEffekt) throw new Error("Zieleffekt fehlt.");

        const casterKorrekt =
            casterEffekt.getFlag("dsk", "isHypnoseCaster") === true &&
            casterEffekt.getFlag("dsk", "verbindungsId") === verbindungsId &&
            casterEffekt.getFlag("dsk", "partnerUuid") === targetActor.uuid;

        const zielKorrekt =
            zielEffekt.getFlag("dsk", "isHypnotisiert") === true &&
            zielEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            zielEffekt.getFlag("dsk", "verbindungsId") === verbindungsId &&
            zielEffekt.getFlag("dsk", "partnerUuid") === casterActor.uuid &&
            zielEffekt.changes.some(c =>
                c.key === "system.status.paralyzed" &&
                Number(c.mode) === 2 &&
                Number(c.value) === 1
            );

        if (!casterKorrekt || !zielKorrekt) throw new Error("Hypnose unvollständig.");
        return true;
    } catch (error) {
        console.error("Hypnotisches Starren: Effektanlage fehlgeschlagen.", error);
        if (zielEffekt) try { await zielEffekt.delete(); } catch {}
        if (casterEffekt) try { await casterEffekt.delete(); } catch {}
        return false;
    }
};

// +++ 6 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;
    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) return false;

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) return false;

    const { actor: targetActor } = await ladeZiel(daten.target);
    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const targetName = daten.target?.name || targetActor?.name || "Unbekanntes Ziel";
    const misserfolge = [];

    const erfolgreich = Boolean(
        targetActor &&
        DSK_FW.Wesen.IstLebendig(targetActor) &&
        await wendeHypnoseAn({
            casterActor, casterName, targetActor, targetName, qs,
            verbindungsId: daten.verbindungsId
        })
    );

    if (!erfolgreich) misserfolge.push({ name: targetName });

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId, gabenName: vollerName, ahne,
        beschreibung: daten.beschreibung, wirkender: casterName,
        ziele: erfolgreich ? [{ name: targetName, rolle: "Hypnotisiertes Ziel" }] : [],
        misserfolge, dauerText: `${qs * 5} Kampfrunden`, erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Hypnose zwischen ${casterName} und ${targetName} hergestellt.`);
    else ui.notifications.error("Luna sagt 🌙: Hypnotisches Starren konnte nicht angewendet werden!");

    return true;
};

// +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);
    if (anfragen.length) {
        for (const actor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(actor, flagKey);
            if (daten && await verarbeiteAnfrage(actor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(actor, flagKey);
            }
        }
        return;
    }
}

// +++ 8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
if (!casterActor) casterActor =
    canvas.tokens.placeables.map(t => t.actor).find(a => a?.getFlag("world", "letzteGabenQS") !== undefined) ||
    game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined) || null;

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Hypnotisches Starren Probe", "Hypnotisches Starren"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Der unheilvolle Blick konnte das Ziel nicht in seinen Bann ziehen.",
        wirkender: casterName, ziele: [], misserfolge: [{ name: casterName }],
        dauerText: "0 Kampfrunden", gmBereich: false,
        angewendet: true, erfolgreich: false, anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

// +++ 9 - ZIEL PRÜFEN +++++++++++++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);
const misserfolge = [];
let targetDaten = null;
let targetName = targets[0]?.name || targets[0]?.actor?.name || "Unbekanntes Ziel";

if (targets.length !== 1) {
    if (targets.length) {
        for (const token of targets) misserfolge.push({ name: token.name || token.actor?.name || "Unbekannt" });
    } else {
        misserfolge.push({ name: casterName });
    }
} else {
    const targetToken = targets[0], targetActor = targetToken?.actor;
    targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

    const gueltig =
        targetActor &&
        targetActor.uuid !== casterActor.uuid &&
        targetActor.id !== casterActor.id &&
        DSK_FW.Wesen.IstLebendig(targetActor) &&
        DSK_FW.Geometrie.Distanz(casterToken, targetToken) <= reichweite;

    if (gueltig) targetDaten = DSK_FW.Target.Merken(targetToken);
    else misserfolge.push({ name: targetName });
}

const dauerText = `${qs * 5} Kampfrunden`;
const beschreibung = beschreibungFuer(casterName, targetName);

if (!targetDaten) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [], misserfolge, dauerText,
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

// +++ 10 - GEMEINSAME KARTE + GM-ANFRAGE ++++++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: [{ name: targetName, rolle: "Hypnotisiertes Ziel" }],
    misserfolge: [], dauerText,
    gmLink, gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    target: targetDaten, qs,
    verbindungsId: `hypnose-${Date.now()}-${foundry.utils.randomID()}`,
    beschreibung, sceneId: canvas.scene?.id || null,
    messageId: nachricht.id, macroUuid, erstellt: Date.now()
};

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Hypnotisches Starren wurde bei der Spielleitung beantragt.");

}).call(this);
